import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to match specific ELA features.
    It combines a skewed quadratic bowl, sinusoidal modulation, and pairwise interactions.

    Formula:
    f(x) = quadratic_bowl(x) + sinusoidal_modulation(x) + interaction_term(x)
    """

    def quadratic_bowl(x):
        """Skewed quadratic bowl."""
        return np.sum((x - 1)**2) + 0.1 * np.sum(np.maximum(0, x)) # introduce skew

    def sinusoidal_modulation(x):
        """Sinusoidal modulation with different frequencies."""
        return 0.5 * np.sum(np.sin(2 * x + np.pi/4) + 0.2 * np.sin(5 * x)) # Different freqs create variety


    def interaction_term(x):
        """Pairwise interaction term."""
        interaction = 0
        for i in range(len(x)):
            for j in range(i + 1, len(x)):
                interaction += 0.1 * x[i] * x[j]
        return interaction

    return quadratic_bowl(x) + sinusoidal_modulation(x) + interaction_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a skewed quadratic bowl with
    oscillatory modulation and pairwise interactions.

    Formula:
    f(x) =  quadBowl(x) + oscillatoryModulation(x) + interactionTerm(x)

    Where:
    - quadBowl(x) = (x[0]**2 + x[1]**2) * (1 + 0.5 * x[0])  (Introduces skewness)
    - oscillatoryModulation(x) =  np.sin(3*x[0]) * np.cos(3*x[1]) * 0.1
                                  (Adds local optima and alters the curvature)
    - interactionTerm(x) = x[0] * x[1] * 0.05      (Introduces linear interaction)
    """

    def quadBowl(x):
        return (x[0]**2 + x[1]**2) * (1 + 0.5 * x[0])

    def oscillatoryModulation(x):
        return np.sin(3*x[0]) * np.cos(3*x[1]) * 0.1

    def interactionTerm(x):
        return x[0] * x[1] * 0.05


    return quadBowl(x) + oscillatoryModulation(x) + interactionTerm(x)
